# -*- coding: utf-8 -*-
import json, re, datetime, sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import omr
SUP = {'2': '²', '3': '³'}
def plain(t):
    t = '$'.join(p.replace('-', '−') if i % 2 else p for i, p in enumerate(t.split('$')))
    t = t.replace('$', '')
    t = t.replace('{,}', ',').replace('\\,', ' ').replace('\\ ', ' ').replace('\\cdot', '·').replace('\\neq', '≠').replace('\\left', '').replace('\\right', '').replace('\\{', '{').replace('\\}', '}')
    def fr(mm):
        n_, d_ = mm.group(1), mm.group(2)
        wrap = lambda x: '(%s)' % x if re.search(r'[+\-−a-z·:]', x) and len(x) > 1 else x
        return '%s/%s' % (wrap(n_), wrap(d_))
    for _ in range(3): t = re.sub(r'\\frac\{([^{}]*)\}\{([^{}]*)\}', fr, t)
    t = re.sub(r'\^\{(\d)\}', lambda m: SUP.get(m.group(1), '^' + m.group(1)), t)
    t = re.sub(r'(−?)(\d+) (\d+/\d+)', r'(\1\2 \3)', t)
    return t.replace('\u00a0', ' ').replace('  ', ' ').replace('{', '').replace('}', '').strip()

def heading(w):
    t = w['title']
    if t.startswith('Суммативное'): return t
    if w['id'].endswith('Q1'): return 'Суммативное оценивание за 1 четверть'
    if w['id'].endswith('Q2'): return 'Суммативное оценивание за 2 четверть'
    return 'Суммативное оценивание за раздел «%s»' % t

def build(db_path, ids, program, quarter, out_path, tag_note):
    D = json.load(open(db_path, encoding='utf8'))
    W = [w for w in D['works'] if w['id'] in ids]; W.sort(key=lambda w: ids.index(w['id']))
    L = []; a = L.append
    a('# БЛОК ПРОВЕРКИ БЛАНКОВ — %s, %s четверть (%s)' % ('математика 6 класс', quarter, program))
    a('')
    a('> Автономная инструкция для отдельного чата. Версия от %s. Прикрепите этот файл **один раз в начале чата**, затем для каждой партии пишите ровно: **«Делай анализ»** и прикладывайте фото. **На одном фото может быть от 1 до 4 бланков** (2 рядом, 3, 2×2 и т. д.), листы могут лежать вразнобой и быть повёрнуты на 90° или 180°. Число бланков и их принадлежность ассистент определяет сам.' % datetime.date.today().isoformat())
    a('')
    a('## 0. РЕЖИМ РАБОТЫ (обязательно)')
    a('1. Если пользователь прислал **только этот файл** без фото — ответьте одной строкой: «Блок загружен: %s, %s четверть. Пришлите «Делай анализ» и фото бланков» — и больше ничего.' % (program, quarter))
    a('2. Команда **«Делай анализ»** + фото: **сразу выполняйте весь разбор без уточняющих вопросов и без пересказа инструкции**. Если команда пришла без фото — одной строкой попросите фото.')
    a('3. **Число бланков на фото заранее не известно.** На одном фото может быть 1, 2, 3 или 4 бланка (если всего бланков нечётное число, часть фото содержит один бланк, например 5 бланков = 2 + 2 + 1). Поэтому для **каждого фото сначала определите, сколько на нём бланков**, затем обработайте каждый бланк отдельно как самостоятельную работу.')
    a('4. **Как найти и посчитать бланки на фото:** бланк — белый прямоугольник A4 с четырьмя чёрными квадратными метками по углам (одна метка с белым центром), строкой «Суммативное оценивание…», полем «Фамилия, имя» и рядами кружков. Считайте по заголовкам и меткам; перекрывающиеся, обрезанные или сильно перспективные бланки тоже считайте и проверяйте — если часть бланка не видна, проверьте видимые задания, а невидимые пометьте «не видно» (REVIEW). В начале ответа напишите, сколько бланков найдено на каждом фото; если сомневаетесь в количестве — назовите найденное число и продолжайте.')
    a('5. **Ориентация.** Бланк может быть повёрнут на 90° (вбок) или на 180° (вверх ногами), либо лежать под углом. Мысленно поверните каждый бланк в нормальное положение: заголовок читается слева направо вверху, метка с белым центром — в правом нижнем углу, номера заданий идут сверху вниз. Только после этого читайте кружки. Разные бланки на одном фото могут быть повёрнуты по-разному.')
    a('6. **Порядок и принадлежность.** Нумеруйте листы «фото N / бланк M» (внутри фото — слева направо и сверху вниз в обычном положении страницы). Принадлежность определяйте **по фамилии и имени на каждом бланке отдельно**; два бланка на одном фото не обязательно принадлежат одному ученику. Если у нескольких бланков одинаковые ФИО и класс (например, СОР и СОЧ одного ученика), объедините их в одну строку ученика в сводке; при малейшем сомнении (разный почерк, похожие, но не совпадающие фамилии) не объединяйте. ФИО неразборчиво — «ФИО не распознано», работу ученику не приписывать.')
    a('7. Все данные для проверки (ключи, цели, шкала, формат вывода) — только в этом файле. Ничего внешнего не нужно. Если учитель в сообщении прямо указал иное (другой ключ, шкала, замена задания), его указание главнее файла. Сначала внимательно рассмотрите каждое изображение (при необходимости по частям); код, если доступен, — только для подсчётов; ключи берите **только отсюда**.')
    a('8. **Не выдавайте предположение за достоверно прочитанный ответ.** Сомнительное — статус REVIEW с указанием «фото N / бланк M» и номера задания. Бланк нечитаем/не тот блок — так и скажите и попросите переснять **это** фото (бланки лучше раскладывать на тёмный фон, не накладывая друг на друга).')
    a('9. Вопросы допустимы **только** по нечитаемым местам. Не заявляйте результат проверки, если фото не рассматривали.')
    a('')
    a('## 1. Как устроен бланк')
    a('Один бланк = одна сторона A4 = одна работа одного варианта (на фото их может быть несколько). Вверху строка «Суммативное оценивание за раздел «…»» или «за 1/2 четверть» %s, поля «Фамилия, имя» и «Класс» (заполняет ученик), крупно справа «Вариант N», полоска из 12 чёрно-белых квадратиков (служебный код). По углам чёрные метки. Затем задания; **у каждого варианта ответа слева кружок, справа от него жирная буква А, Б, В или Г**. Ученик полностью закрашивает один кружок. Кружок принадлежит букве, рядом с которой стоит; варианты могут быть в одну строку, в две строки (А Б / В Г) или столбиком.' % tag_note)
    a('')
    a('**Работы этого блока** (определяйте по заголовку, числу заданий и «Вариант N»):')
    a('')
    a('| Заголовок на листе | Заданий | Макс. балл | Служебный код (В1 / В2 / В3 / В4) |')
    a('|---|---|---|---|')
    for w in W:
        codes = ' / '.join('`%s`' % ''.join(map(str, omr.id_bits(w['template_index'], v))) for v in (1, 2, 3, 4))
        a('| %s | %d | %d | %s |' % (heading(w), w['n_items'], w['max_points'], codes))
    a('')
    a('Служебный код (запасной способ определить работу): 12 квадратиков, чёрный = 1: `1` | 6 бит номера шаблона | 2 бита (вариант−1) | чётность | `0` | `1`. Бланк из другой четверти/программы (иной заголовок или число заданий) — не проверяйте по этому блоку, сообщите об этом.')
    a('')
    a('## 2. КЛЮЧИ, ЦЕЛИ И ТЕКСТЫ ЗАДАНИЙ')
    a('1 балл за каждое задание. «Цель» — код цели обучения из программы; «Навык» — что проверяет задание.')
    a('')
    for w in W:
        a('### %s (%d заданий)' % (heading(w), w['n_items']))
        a('')
        a('| № | Тема | Цель | Навык | В1 | В2 | В3 | В4 |')
        a('|---|---|---|---|---|---|---|---|')
        for it in w['items']:
            a('| %d | %s | %s | %s | %s |' % (it['no'], it['topic'], it['goal'], it['skill'], ' | '.join(it['variants'][str(n)]['key'] for n in (1, 2, 3, 4))))
        a('')
        for n in (1, 2, 3, 4):
            a('**%s, вариант %d.** Ключ: ' % (heading(w), n) + ' '.join('%d%s' % (it['no'], it['variants'][str(n)]['key']) for it in w['items']))
            a('')
            for it in w['items']:
                v = it['variants'][str(n)]
                ops = '; '.join('%s) %s' % ('АБВГ'[k], plain(o)) for k, o in enumerate(v['options']))
                fig = ' [рисунок: числовая прямая с точками A(%d), B(%d)]' % (v['figure']['a'], v['figure']['b']) if v.get('figure') else ''
                a('%d. [ключ %s] %s%s — %s' % (it['no'], v['key'], plain(v['stem']), fig, ops))
            a('')
    a('## 3. Чтение кружков')
    a('- **ok** — закрашен ровно один кружок (явная заливка; допускается неполная, но очевидная).')
    a('- **пропуск** — все кружки пусты. **Несколько отметок** — два и более закрашенных → ответ не засчитывается («2 отм.»).')
    a('- **Сомнительно (REVIEW)** — точка, штрих, зачёркивание, слабая заливка: выбор неясен. Не засчитывайте автоматически, перечислите учителю.')
    a('- Верно только при статусе ok и совпадении буквы с ключом. Пропуск/несколько отметок/сомнительно = 0 баллов, но в аналитике считаются отдельно.')
    a('- Для самопроверки выписывайте строку ответов: `1Б 2А 3— 4В 5(А,Г) 6Б?` (— пропуск, (А,Г) несколько отметок, ? сомнительно).')
    a('')
    a('## 4. Подсчёт')
    a('Баллы = число верных; процент = баллы / максимум × 100. **Рабочая шкала** (если учитель не задал другую): 5 — от 85%; 4 — 65–84%; 3 — 40–64%; 2 — менее 40%. Цель у ученика: **освоена** — верны все задания по цели; **частично**; **пробел** — ни одного верного (заданий на цель 1–4, выводы осторожные).')
    a('')
    a('## 5. ФОРМАТ ОТВЕТА НА «Делай анализ»')
    a('Выдайте строго в таком порядке, без вступлений:')
    a('1. **Сколько бланков найдено:** по каждому фото — число и коротко (например: «Фото 1: 2 бланка; фото 2: 1 бланк; всего 3»).')
    a('2. **Проблемы чтения** (только если есть): «фото N / бланк M», что не читается/сомнительно (номер задания), повёрнут ли бланк.')
    a('3. **Таблица результатов** (все бланки в порядке «фото → бланк»): фото/бланк | ФИО | класс | работа и вариант | строка ответов | верных/макс | % | отметка | примечание (REVIEW).')
    a('4. **По каждому бланку** (кратко, 2–5 строк): неверные задания — «№N (цель; навык): выбрано X, верно Y» + при необходимости осторожная гипотеза словом «возможно» (по тексту выбранного ответа); освоенные цели; цели-пробелы; 1–2 рекомендации по коррекции. Не утверждайте причину ошибки по одному выбору: различайте **установленный пробел** и **гипотезу**.')
    a('5. **Сводка по ученикам**, у которых несколько бланков (по совпадающим ФИО): одна строка на ученика — результаты по каждой работе.')
    a('6. **Если бланков одной работы два и больше** — мини-сводка: средний %, распределение отметок, успешность по заданиям (% верных), самые частые неверные ответы, кому нужна помощь (менее 40% или два и более пробелов по целям). Бланки разных работ — сводка по каждой работе отдельно.')
    a('7. Одна строка в конце: «Сомнительных мест: k» и что нужно подтвердить.')
    a('Объём пояснений — до 250 слов сверх таблиц. Если среда позволяет создавать файлы и пользователь просит — приложите CSV/HTML-отчёт; по умолчанию вывод только в чате.')
    a('')
    a('## 6. Ограничения (сообщать при необходимости)')
    a('Комплект проверен на смоделированных фото; на реальных фото возможны тени, блики, неровная заливка, а при 3–4 бланках на кадре кружки мелкие — поэтому всегда показывайте строку ответов, чтобы учитель мог сверить, и при плохом разрешении просите переснять (лучше не более 2×2 бланков на кадр). ФИО распознаётся только если разборчиво написано. Практические цели (построение, измерение, циркуль, размен купюр и т. п.) в кружки не переводились — учитель оценивает отдельно.')
    open(out_path, 'w', encoding='utf8').write('\n'.join(L))
    return len('\n'.join(L))

OUT = '/home/user/KAP_1/work/out4'; os.makedirs(OUT, exist_ok=True)
MAIN = '/home/user/KAP_1/diagnostic/Diagnostic_DB.json'; LMD = '/home/user/KAP_1/diagnostic/oblegchennaya/Diagnostic_DB_oblegchennaya.json'
