print(build(MAIN, ['SOR-6-3', 'SOR-6-4', 'SOCH-6-Q2'], 'основной класс', '2', OUT + '/Blok_2chetvert_6klass.md', ''))
print(build(LMD, ['LMD-SOR-1', 'LMD-SOR-2', 'LMD-SOCH-Q1'], 'облегчённая программа', '1', OUT + '/Blok_1chetvert_oblegchennaya.md', 'и пометка «облегчённая программа»'))
print(build(LMD, ['LMD-SOR-3', 'LMD-SOR-4', 'LMD-SOCH-Q2'], 'облегчённая программа', '2', OUT + '/Blok_2chetvert_oblegchennaya.md', 'и пометка «облегчённая программа»'))
